import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"与《文明5》的有意差异","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Other/Intentional-departures-from-Civ-V.md","filePath":"zh/Other/Intentional-departures-from-Civ-V.md"}'),n={name:"zh/Other/Intentional-departures-from-Civ-V.md"};function i(h,a,s,l,p,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="与《文明5》的有意差异" tabindex="-1">与《文明5》的有意差异 <a class="header-anchor" href="#与《文明5》的有意差异" aria-label="Permalink to &quot;与《文明5》的有意差异&quot;">​</a></h1><h2 id="水面近战单位可以攻击岸上的陆地单位" tabindex="-1">水面近战单位可以攻击岸上的陆地单位 <a class="header-anchor" href="#水面近战单位可以攻击岸上的陆地单位" aria-label="Permalink to &quot;水面近战单位可以攻击岸上的陆地单位&quot;">​</a></h2><p>Discord 投票的结果。文明5中的水面近战单位相当弱势，以至于即使在有水的地图上也不被认为有竞争力。</p><p>这个改动让水面近战单位重新有了值得建造的价值。</p><h2 id="工人不会在同一回合完成改良设施——他们会接到-去工作-的指令" tabindex="-1">工人不会在同一回合完成改良设施——他们会接到&quot;去工作&quot;的指令 <a class="header-anchor" href="#工人不会在同一回合完成改良设施——他们会接到-去工作-的指令" aria-label="Permalink to &quot;工人不会在同一回合完成改良设施——他们会接到&quot;去工作&quot;的指令&quot;">​</a></h2><p>这让玩家可以指派工人去改良地块，然后重新考虑、更改改良设施或把他们派去别处。</p><p>建造东西需要时间！</p><h2 id="森林和丛林在视野范围外-1-格处可见" tabindex="-1">森林和丛林在视野范围外 1 格处可见 <a class="header-anchor" href="#森林和丛林在视野范围外-1-格处可见" aria-label="Permalink to &quot;森林和丛林在视野范围外 1 格处可见&quot;">​</a></h2><p>在文明5中，丘陵和山脉有这个行为，但丛林和森林没有。</p><p>然而，丛林和森林<em>可以</em>遮挡丘陵，丘陵+森林可以遮挡山脉——所以它们的高度必然相同！</p><p>考虑到文明5其他方面结构良好的视野逻辑，这部分完全没有道理，我们认为这是个 bug。</p><h2 id="大战争之路不为连接的城市提供铁路加成" tabindex="-1">大战争之路不为连接的城市提供铁路加成 <a class="header-anchor" href="#大战争之路不为连接的城市提供铁路加成" aria-label="Permalink to &quot;大战争之路不为连接的城市提供铁路加成&quot;">​</a></h2><p>这是<a href="https://github.com/yairm210/Unciv/issues/12261" target="_blank" rel="noreferrer">文明5规则中的一个矛盾</a>——如果所有丛林都像道路，那么在生产上它们就不应该被当作铁路。</p><p>思路是：如果铁路能快速运输货物并获得生产加成——那么快速穿越丛林或许可以，但不可能运载工业级的货物量。</p>',14)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
